import csv
import io
import re
from typing import List, Dict, Any, Optional

def parse_csv(raw_csv: str):
    if raw_csv is None:
        raw_csv = ""
    text = raw_csv.lstrip("\ufeff")
    if not text.strip():
        return {"columns": [], "rows": []}

    lines = text.splitlines()
    if not lines:
        return {"columns": [], "rows": []}

    def split_fields(line: str) -> List[str]:
        try:
            return next(csv.reader([line], delimiter=",", quotechar='"', doublequote=True, skipinitialspace=False))
        except Exception:
            return [x.strip() for x in line.split(",")]

    # Find first plausible header row
    header_idx = 0
    header = split_fields(lines[0])
    expected_width = 9

    # Skip preamble lines until a row with at least 2 comma-separated fields and likely header-like content
    for i, line in enumerate(lines[: min(len(lines), 20)]):
        fields = split_fields(line)
        if len(fields) >= 2:
            header_idx = i
            header = fields
            break

    # Handle multi-line header if first row is a partial preamble/header and next row looks like actual header
    if header_idx + 1 < len(lines):
        next_fields = split_fields(lines[header_idx + 1])
        if len(header) != expected_width and len(next_fields) == expected_width:
            # Prefer the row with expected width as header if the first is malformed/duplicate-like
            if all(re.match(r"^[A-Za-z][A-Za-z0-9 _/-]*$", f.strip()) for f in next_fields):
                header_idx += 1
                header = next_fields

    # If header has quoted duplicates or malformed widths, normalize by taking the widest plausible header row nearby
    if len(header) != expected_width:
        best_idx = header_idx
        best = header
        for j in range(header_idx, min(len(lines), header_idx + 5)):
            fields = split_fields(lines[j])
            if len(fields) == expected_width:
                best_idx = j
                best = fields
                break
        header_idx = best_idx
        header = best

    # Parse remaining physical lines into logical CSV rows using csv.reader over the tail text
    tail_text = "\n".join(lines[header_idx:])
    reader = csv.reader(io.StringIO(tail_text), delimiter=",", quotechar='"', doublequote=True, skipinitialspace=False)

    rows: List[List[str]] = []
    try:
        parsed = list(reader)
    except Exception:
        parsed = []

    if not parsed:
        return {"columns": header if header else [], "rows": []}

    # Use first parsed row as header if it matches or is close; otherwise keep detected header
    data_start = 1
    if len(parsed[0]) == expected_width:
        header = parsed[0]
    else:
        data_start = 0

    for row in parsed[data_start:]:
        if not row:
            continue
        if len(row) < expected_width:
            row = row + [""] * (expected_width - len(row))
        elif len(row) > expected_width:
            row = row[:expected_width - 1] + [",".join(row[expected_width - 1:])]
        rows.append([str(v) for v in row])

    return {"columns": [str(v) for v in header], "rows": rows}
